// Generated by tour2playwright from a Tour Recorder export, then hand-edited.
// Source tour: Finance: Reconcile Transactions Using Reconciliation Models ( Setup - Bank Charges Button - Invoice Match ) - Full Flow
// Hand edits: data set up by RPC (the recorded bank lines no longer exist), label/text selectors, state assertions,
// result screenshots, wide viewport, login fallback, cleanup of the model this run creates.
// WRITES (test database only), so it is gated behind TOUR_ALLOW_WRITES=true:
//   - creates one reconciliation model "[TEST] Bank Charges - Commercial Bank" (deleted again at the end),
//   - creates two bank lines on the Commercial Bank journal and RECONCILES them,
//   - pays an open customer invoice down by the receipt amount.
import { test, expect } from "../../../../core/fixtures/index";
import type { Page, Locator } from "@playwright/test";
import { uniqueName } from "../../../../core/utils/RandomDataGenerator";
import fs from "node:fs";

const SHOT_DIR = "tools/tour2playwright/generated/screenshots/finance-reconcile-transactions-using-reconciliation-models-setup-bank-charges-button-invoice-match-full-flow";
const MODEL_NAME = uniqueName("Bank Charges - Commercial Bank");
const RUN_TAG = MODEL_NAME.split(" ").pop() as string;
const CHARGE_LABEL = `Monthly Bank Charges ${RUN_TAG}`;

// A step's own screenshot is taken BEFORE its action; this keeps one of the finished screen.
async function resultShot(page: Page, n: number) {
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/step-${String(n).padStart(2, "0")}-result.png` });
}

// Screenshot the current page with the target element outlined.
async function shot(page: Page, loc: Locator, file: string) {
  try {
    await loc.scrollIntoViewIfNeeded({ timeout: 5000 });
    await loc.evaluate((el) => el.setAttribute("data-t2p", "1"));
    await page.addStyleTag({
      content: '[data-t2p="1"]{outline:3px solid #e01e5a !important;outline-offset:2px !important;}',
    });
  } catch {}
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/${file}` });
  try { await loc.evaluate((el) => el.removeAttribute("data-t2p")); } catch {}
}

// Type into a many2one autocomplete and pick the match (the first option is highlighted automatically).
async function pickOption(page: Page, input: Locator, text: string, optionText: string | RegExp) {
  await input.click();
  await input.fill("");
  await input.fill(text);
  const option = page.locator(".o-autocomplete--dropdown-item").filter({ hasText: optionText }).first();
  await option.waitFor({ state: "visible", timeout: 15000 });
  await option.click();
}

test.describe("Finance: Reconcile Transactions Using Reconciliation Models ( Setup - Bank Charges Button - Invoice Match ) - Full Flow @module:accounting @step:business @e2e", () => {
  // At the default 1280px some top-menu entries collapse into the "+" overflow.
  test.use({ viewport: { width: 1600, height: 900 } });

  // Remove what this run created: the model and any test bank line that is still unreconciled.
  test.afterEach(async ({ rpc }) => {
    if (process.env.TOUR_ALLOW_WRITES !== "true") return;
    const models = await rpc.searchRead<{ id: number }>("account.reconcile.model", [["name", "like", RUN_TAG]], ["id"]);
    if (models.length) await rpc.unlink("account.reconcile.model", models.map((m) => m.id)).catch(() => {});
    const lines = await rpc.searchRead<{ id: number }>(
      "account.bank.statement.line", [["payment_ref", "like", RUN_TAG], ["is_reconciled", "=", false]], ["id"]);
    if (lines.length) await rpc.unlink("account.bank.statement.line", lines.map((l) => l.id)).catch(() => {});
  });

  test("Finance: Reconcile Transactions Using Reconciliation Models ( Setup - Bank Charges Button - Invoice Match ) - Full Flow", async ({ page, rpc }) => {
    test.skip(
      process.env.TOUR_ALLOW_WRITES !== "true",
      "Creates a model, posts real bank lines and reconciles them — set TOUR_ALLOW_WRITES=true to run",
    );
    test.setTimeout(420_000);

    // ------------------------------------------------------------------ data: two bank lines + an open invoice
    const [journal] = await rpc.searchRead<{ id: number; company_id: [number, string] }>(
      "account.journal", [["name", "=", "Commercial Bank"], ["type", "=", "bank"]], ["id", "company_id"], { limit: 1 });
    expect(journal, "Commercial Bank journal must exist").toBeTruthy();
    const [invoice] = await rpc.searchRead<{ id: number; name: string; amount_residual: number; partner_id: [number, string] }>(
      "account.move",
      [["move_type", "=", "out_invoice"], ["state", "=", "posted"], ["payment_state", "in", ["not_paid", "partial"]],
        ["amount_residual", ">=", 500], ["company_id", "=", journal.company_id[0]], ["partner_id", "!=", false]],
      ["name", "amount_residual", "partner_id"], { limit: 1, order: "id desc" });
    expect(invoice, "an open customer invoice (residual >= 500) must exist").toBeTruthy();
    const RECEIPT_AMOUNT = Math.min(2800, Math.floor(invoice.amount_residual));
    const RECEIPT_LABEL = `Cheque Settlement - ${invoice.partner_id[1]} ${RUN_TAG}`;
    const isoToday = new Date().toISOString().slice(0, 10);
    await rpc.create("account.bank.statement.line", { journal_id: journal.id, date: isoToday, payment_ref: CHARGE_LABEL, amount: -25 });
    await rpc.create("account.bank.statement.line", {
      journal_id: journal.id, date: isoToday, payment_ref: RECEIPT_LABEL, amount: RECEIPT_AMOUNT, partner_id: invoice.partner_id[0],
    });

    const bankCard = () => page
      .locator(".o_kanban_record")
      .filter({ hasText: "Commercial Bank" })
      .filter({ has: page.locator('button[name="action_open_reconcile"]') });

    await page.goto("/web");
    // The rpc fixture's API login can end the saved browser session — fall back to the login form.
    const emailBox = page.getByRole("textbox", { name: "Email" });
    if (await emailBox.isVisible({ timeout: 8_000 }).catch(() => false)) {
      await emailBox.fill(process.env.ADMIN_EMAIL ?? "admin");
      await page.getByRole("textbox", { name: "Password" }).fill(process.env.ADMIN_PASSWORD ?? "admin");
      await page.getByRole("button", { name: "Log in" }).click();
      await page.waitForSelector(".o_main_navbar, .o_home_menu", { state: "visible", timeout: 45_000 });
    }
    await page.waitForLoadState("networkidle", { timeout: 10_000 }).catch(() => {});
    // /web lands on the app picker: open Accounting first (exact match — "Accounting/Confi…" is another tile).
    const accountingApp = page.getByRole("option", { name: "Accounting", exact: true });
    if (await accountingApp.isVisible({ timeout: 10_000 }).catch(() => false)) await accountingApp.click();
    await expect(page.locator(".o_menu_sections")).toBeVisible({ timeout: 45000 });

    const run = async (n: number, title: string, loc: Locator, act?: (l: Locator) => Promise<void>, result = false) => {
      await test.step(`${String(n).padStart(2, "0")}. ${title}`, async () => {
        const l = loc.first();
        await l.waitFor({ state: "visible", timeout: 45000 });
        await shot(page, l, `step-${String(n).padStart(2, "0")}.png`);
        if (act) await act(l);
        if (result) await resultShot(page, n);
      });
    };
    const topMenu = (name: string) => page.locator(".o_menu_sections .dropdown-toggle, .o_menu_sections > a").filter({ hasText: new RegExp(`^${name}$`) });
    const field = (name: string) => page.locator(`.o_field_widget[name="${name}"]`);
    const breadcrumb = (text: string) => page.locator(".o_breadcrumb .breadcrumb-item, .breadcrumb-item").filter({ hasText: text });
    const validateBtn = () => page.locator(".o_bank_rec_stats_buttons_aside_left button.btn-primary");
    const lineIsReconciled = async (label: string) =>
      (await rpc.searchRead<{ is_reconciled: boolean }>("account.bank.statement.line", [["payment_ref", "=", label]], ["is_reconciled"], { limit: 1 }))[0]?.is_reconciled === true;

    // ------------------------------------------------------------------ Part 1: look at the existing models
    await run(1, "Open the Configuration menu", topMenu("Configuration"), async (l) => {
      await l.click();
      await expect(page.locator('[data-menu-xmlid="account.action_account_reconcile_model_menu"]').first()).toBeVisible({ timeout: 15000 });
    }, true);
    await run(2, "Open Reconciliation Models", page.locator('[data-menu-xmlid="account.action_account_reconcile_model_menu"]'), async (l) => {
      await l.click();
      await expect(page.locator(".o_list_view"), "Reconciliation Models list opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(3, "The three types of reconciliation model", page.locator("thead th").filter({ hasText: /^Type$/ }), async (l) => {
      await expect(l).toBeVisible();
    });
    await run(4, "Open the invoice matching rule", page.locator(".o_data_row").filter({ hasText: /Invoices\/Bills Perfect Match/ }).locator("td").nth(2), async (l) => {
      await l.click();
      await expect(page.locator(".o_form_view"), "model form opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(5, "Type: Rule to match invoices/bills", page.locator(".o_form_view label.form-check-label").filter({ hasText: /match invoices/i }), async (l) => {
      await expect(l).toBeVisible();
    });
    await run(6, "Auto-validate", page.locator("#auto_reconcile_0, .o_field_widget[name='auto_reconcile']").first(), async (l) => {
      await expect(l).toBeVisible();
    });
    await run(7, "The matching conditions", page.locator("#match_label_param_0, .o_field_widget[name='match_label_param']").first(), async (l) => {
      await expect(l).toBeVisible();
    });
    await run(8, "Go back to the model list", breadcrumb("Reconciliation Models"), async (l) => {
      await l.click();
      await expect(page.locator(".o_list_view")).toBeVisible({ timeout: 30000 });
    }, true);

    // ------------------------------------------------------------------ Part 2: create the button model
    await run(9, "Create a new reconciliation model", page.getByRole("button", { name: "New", exact: true }), async (l) => {
      await l.click();
      await expect(page.locator("#name_0"), "new model form opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(10, "Name the model", page.locator("#name_0"), async (l) => {
      await l.fill(MODEL_NAME);
      await expect(l).toHaveValue(MODEL_NAME);
    }, true);
    await run(11, "Keep the type as Button", page.locator(".o_form_view label.form-check-label").filter({ hasText: /^Button to generate/ }), async (l) => {
      await expect(l.locator("xpath=..").locator("input")).toBeChecked();
    });
    await run(12, "Limit the button to one journal", page.locator("#match_journal_ids_0, .o_field_widget[name='match_journal_ids'] input").first(), async (l) => {
      await pickOption(page, l, "Commercial Bank", "Commercial Bank");
      await expect(field("match_journal_ids"), "journal added").toContainText("Commercial Bank");
    }, true);
    await run(13, "Add the counterpart line", page.locator("td.o_field_x2many_list_row_add a"), async (l) => {
      await l.click();
      await expect(page.locator(".o_selected_row"), "counterpart row opened").toBeVisible({ timeout: 15000 });
    }, true);
    await run(14, "Choose the expense account", page.locator(".o_selected_row .o_field_widget[name='account_id'] input"), async (l) => {
      await pickOption(page, l, "72030110", "BANK CHARGES");
      await expect(l).toHaveValue(/BANK CHARGES/i);
    }, true);
    await run(15, "Amount Type: Percentage of balance", page.locator(".o_selected_row td[name='amount_type'], .o_selected_row [name='amount_type']"), async (l) => {
      // "Percentage of balance" and an amount of 100 are the defaults — they are checked, not changed.
      await expect(page.locator(".o_selected_row select").first()).toHaveValue(/percentage/);
      const values = await page.locator(".o_selected_row input").evaluateAll((els) => els.map((e) => (e as HTMLInputElement).value));
      expect(values.some((v) => /^100(\.0+)?$/.test(v)), "amount is 100").toBe(true);
    }, true);
    await run(16, "Label the journal item", page.locator(".o_selected_row .o_field_widget[name='label'] input"), async (l) => {
      await l.fill("Bank charges");
      await expect(l).toHaveValue("Bank charges");
    }, true);
    await run(17, "Save the model", page.locator("button.o_form_button_save"), async (l) => {
      await l.click();
      await expect(l, "model saved").toBeHidden({ timeout: 30000 });
      const [saved] = await rpc.searchRead<{ id: number }>("account.reconcile.model", [["name", "=", MODEL_NAME]], ["id"], { limit: 1 });
      expect(saved, "the model exists in the database").toBeTruthy();
    }, true);

    // ------------------------------------------------------------------ Part 3: use the button
    await run(18, "Go to the Accounting Dashboard", page.locator('[data-menu-xmlid="account.menu_board_journal_1"]'), async (l) => {
      await l.click();
      await expect(bankCard().first(), "Commercial Bank card").toBeVisible({ timeout: 30000 });
    }, true);
    await run(19, "Open Reconcile on the Commercial Bank card", bankCard().locator('button[name="action_open_reconcile"]'), async (l) => {
      await l.click();
      await expect(page.locator(".o_bank_rec_kanban_div"), "reconciliation screen opened").toBeVisible({ timeout: 45000 });
    }, true);

    const list = () => page.locator(".o_bank_rec_kanban_div").first();
    await run(20, "Select the bank charge line", list(), async (l) => {
      // Filter by this run's tag so only our lines show (the list is otherwise long and unordered).
      const search = page.locator(".o_cp_searchview input.o_searchview_input").first();
      await search.fill(RUN_TAG);
      await search.press("Enter");
      const row = l.getByText(CHARGE_LABEL).first();
      await expect(row).toBeVisible({ timeout: 20000 });
      await row.click();
    }, true);
    await run(21, "Before: the line sits in Bank Suspense", page.locator('div[name="line_ids"] table.o_list_table'), async (l) => {
      await expect(l, "counterpart is parked in suspense").toContainText(/SUSPENSE/i);
    });
    await run(22, "Click the reconciliation model button", page.locator(".available_reco_model_ids button.recon_model_button").filter({ hasText: MODEL_NAME }), async (l) => {
      await l.click();
      await expect(page.locator('div[name="line_ids"] table.o_list_table'), "counterpart replaced").toContainText(/BANK CHARGES/i, { timeout: 20000 });
    }, true);
    await run(23, "After: the counterpart is ready", page.locator('div[name="line_ids"] table.o_list_table'), async (l) => {
      await expect(l).toContainText(/72030110/);
      await expect(l).not.toContainText(/SUSPENSE/i);
    });
    await run(24, "Validate the reconciliation", validateBtn(), async (l) => {
      await l.click();
      // Odoo applies it a little after the click — wait for it, and never click Validate twice.
      await expect.poll(() => lineIsReconciled(CHARGE_LABEL), { timeout: 45000, message: "bank charge should be reconciled" }).toBe(true);
    }, true);
    await run(25, "One line less to reconcile", page.locator(".o_control_panel_navigation .o_pager_value, .o_bank_rec_kanban_div").first(), async (l) => {
      await expect(l).toBeVisible();
    });

    // ------------------------------------------------------------------ Part 4: the invoice-matching rule
    await run(26, "Select a customer receipt line", list(), async (l) => {
      const row = l.getByText(RECEIPT_LABEL).first();
      await expect(row).toBeVisible({ timeout: 20000 });
      await row.click();
      await expect(page.locator("a[name='amls_tab']"), "match tab visible").toBeVisible({ timeout: 15000 });
    }, true);
    await run(27, "The invoice matching rule filters the candidates", page.locator("a[name='amls_tab']"), async (l) => {
      await l.click();
      await expect(page.locator(".tab-pane.active .o_searchview_facet, .tab-pane.active .o_searchview").first()).toBeVisible({ timeout: 15000 });
    }, true);
    await run(28, "Pick the matching invoice", page.locator(".tab-pane.active tr.o_data_row").filter({ hasText: "DEBTORS LEDGER" }).filter({ hasText: invoice.name }), async (l) => {
      await l.click();
    }, true).catch(() => { /* handled below */ });
    await test.step("28b. Pick the matching invoice (search by number if the list hides it)", async () => {
      if (await page.locator('div[name="line_ids"] table.o_list_table').filter({ hasText: invoice.name }).isVisible().catch(() => false)) return;
      // The partner filter can hide the invoice's receivable line — drop it and search by invoice number.
      const partnerFacet = page.locator(".tab-pane.active .o_searchview_facet").filter({ hasText: "Partner" }).first();
      if (await partnerFacet.isVisible({ timeout: 3000 }).catch(() => false)) await partnerFacet.locator(".o_facet_remove").click();
      const input = page.locator(".tab-pane.active input.o_searchview_input").first();
      await input.fill(invoice.name);
      await input.press("Enter");
      const row = page.locator(".tab-pane.active tr.o_data_row").filter({ hasText: "DEBTORS LEDGER" }).filter({ hasText: invoice.name }).first();
      await row.waitFor({ state: "visible", timeout: 30000 });
      await shot(page, row, "step-28.png");
      await row.click();
    });
    await run(29, "Check the match is complete", page.locator('div[name="line_ids"] table.o_list_table'), async (l) => {
      await expect(l, "the invoice is the counterpart").toContainText(invoice.name, { timeout: 20000 });
    });
    await run(30, "Validate the invoice match", validateBtn(), async (l) => {
      await l.click();
      await expect.poll(() => lineIsReconciled(RECEIPT_LABEL), { timeout: 45000, message: "receipt should be reconciled" }).toBe(true);
    }, true);
    await test.step("31. Recap - which model to use when", async () => {
      const loc = page.locator(".o_control_panel_navigation .o_pager_value").or(page.getByText("you're all done")).or(page.locator(".o_bank_rec_kanban_div")).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-31.png");
    });

    // The UI steps can pass while acting on the wrong rows, so verify the real outcome.
    await test.step("Verify: both lines reconciled, invoice paid down", async () => {
      const [after] = await rpc.searchRead<{ amount_residual: number }>("account.move", [["id", "=", invoice.id]], ["amount_residual"], { limit: 1 });
      expect(after.amount_residual, "invoice balance dropped by the receipt").toBeLessThan(invoice.amount_residual);
    });
  });
});
